const pages = $('Get_Case_Comment').all().map(item => item.json || {});
const webhookBody = $('Zen_New_Comment_Webhook').first().json?.body || {};

if (!pages.length) {
  throw new Error('Get_Case_Comment returned no pages');
}

const comments = pages.flatMap(page =>
  Array.isArray(page.comments) ? page.comments : []
);

const users = pages.flatMap(page =>
  Array.isArray(page.users) ? page.users : []
);

if (!comments.length) {
  throw new Error('Zendesk comments response is empty');
}

const firstCount = pages[0]?.count;
const expectedCount =
  firstCount === null || firstCount === undefined || firstCount === ''
    ? null
    : Number(firstCount);

const lastPage = pages[pages.length - 1];

if (
  lastPage.next_page != null ||
  (
    expectedCount !== null &&
    Number.isFinite(expectedCount) &&
    comments.length !== expectedCount
  )
) {
  throw new Error(
    `Zendesk comment snapshot is incomplete: expected=${expectedCount}, received=${comments.length}`
  );
}

const userById = new Map(
  users
    .filter(user => user && user.id !== null && user.id !== undefined)
    .map(user => [String(user.id), user])
);

function staffFlag(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }

  if (typeof value.is_staff === 'boolean') {
    return value.is_staff;
  }

  if (typeof value.is_agent === 'boolean') {
    return value.is_agent;
  }

  const role = String(value.role || '').trim().toLowerCase();

  if (['agent', 'admin', 'staff', 'support'].includes(role)) {
    return true;
  }

  if (['end-user', 'end_user', 'customer', 'requester', 'user'].includes(role)) {
    return false;
  }

  return null;
}

const eventComment = webhookBody.event?.comment || {};
const eventCommentId = String(eventComment.id || '');
const eventAuthor =
  eventComment.author && typeof eventComment.author === 'object'
    ? eventComment.author
    : {};

const commentsPayload = comments.map(comment => {
  const commentId = String(comment.id);
  const commentAuthorId =
    comment.author_id === null || comment.author_id === undefined
      ? null
      : String(comment.author_id);

  const currentAuthor =
    commentId === eventCommentId
      ? eventAuthor
      : {};

  const currentAuthorId =
    commentAuthorId || (
      currentAuthor.id === null || currentAuthor.id === undefined
        ? null
        : String(currentAuthor.id)
    );

  const user = currentAuthorId
    ? userById.get(currentAuthorId)
    : null;

  const userIsAgent = staffFlag(user);
  const webhookIsAgent =
    commentId === eventCommentId
      ? staffFlag(currentAuthor)
      : null;

  if (
    userIsAgent !== null &&
    webhookIsAgent !== null &&
    userIsAgent !== webhookIsAgent
  ) {
    throw new Error(`Author identity conflict for comment ${commentId}`);
  }

  const isAgent =
    userIsAgent !== null
      ? userIsAgent
      : webhookIsAgent;

  const role =
    isAgent === true
      ? 'agent'
      : isAgent === false
        ? 'end-user'
        : 'unknown';

  const isPublic =
    typeof comment.public === 'boolean'
      ? comment.public
      : comment.is_public === true;

  return {
    id: comment.id,
    public: isPublic,
    author: {
      id: currentAuthorId,
      name: user?.name || comment.author_name || currentAuthor.name || null,
      role,
      is_agent: isAgent
    },
    body: String(comment.body ?? comment.plain_body ?? ''),
    via_channel: comment.via?.channel ?? null,
    created_at: comment.created_at
  };
});

const latestCommentAt = comments
  .map(comment => String(comment.created_at || '').trim())
  .filter(Boolean)
  .sort()
  .at(-1);

const sourceUpdatedAt = String(
  webhookBody.detail?.updated_at ||
  webhookBody.time ||
  latestCommentAt ||
  ''
).trim();

if (!sourceUpdatedAt) {
  throw new Error('source_updated_at is missing');
}

return [
  {
    json: {
      source_updated_at: sourceUpdatedAt,
      snapshot_complete: true,
      trigger_comment_id: eventCommentId, 
      comments: commentsPayload
    }
  }
];

